    "wardrobe": "Soft, draped blouses in warm neutrals (peach, sage, cream)",
    "accessories": "Minimal gold jewelry (small hoops, delicate necklace)",
    "lighting": "Cinematic with warm tones, ring light accent visible"
  },
  "camera_rules": {
    "key_lines": "Chest-up framing, direct eye contact",
    "product_demos": "Wide shot with UI overlay",
    "transitions": "Smooth push-ins for emphasis, quick cuts for tool parade chaos",
    "end_cards": "Medium shot with CTA overlay"
  },
  "non_negotiables": [
    "Never mention tool parade without naming 4+ specific tools",
